  1	//! Disposable interpretations of retained capture bytes. No storage or authority.
  2	//!
  3	//! Callers must obtain bytes through an authorized, verified occurrence. Successful
  4	//! decoding does not verify a signature, grant access, or prove capture coverage.
  5	use crate::evidence_capture::{Event, Header, CHUNK};
  6	use serde::de::{self, MapAccess, SeqAccess, Visitor};
  7	use serde::{Deserialize, Deserializer};
  8	use serde_json::{Map, Number, Value};
  9	use std::{fmt, ops::Range};
 10	
 11	pub const MAX_HEADER: usize = 128 * 1024;
 12	pub const MAX_FRAME: usize = 9 + MAX_HEADER + CHUNK;
 13	
 14	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
 15	pub enum Unsupported {
 16	    Envelope,
 17	    Version,
 18	    Observer,
 19	    Event,
 20	    Outcome,
 21	}
 22	
 23	#[derive(Debug, thiserror::Error, Clone, Copy, PartialEq, Eq)]
 24	pub enum Error {
 25	    #[error("capture frame exceeds decoder limits")]
 26	    Limit,
 27	    #[error("malformed capture envelope")]
 28	    Envelope,
 29	    #[error("malformed capture header")]
 30	    Header,
 31	    #[error("capture event contradicts its body shape")]
 32	    Body,
 33	}
 34	
 35	#[derive(Debug)]
 36	pub enum Decoded<'a> {
 37	    /// No recognized capture magic; the caller retains its original raw input.
 38	    Opaque,
 39	    /// No semantic interpretation. The caller still retains its original input.
 40	    Unsupported(Unsupported),
 41	    Capture(Frame<'a>),
 42	}
 43	
 44	#[derive(Debug)]
 45	pub struct Frame<'a> {
 46	    pub header: Header,
 47	    pub body: &'a [u8],
 48	    /// Exclusive byte coordinates in the original decrypted frame, not characters.
 49	    pub header_span: Range<usize>,
 50	    pub body_span: Range<usize>,
 51	}
 52	
 53	/// Decode one complete decrypted frame, never a source-range fragment.
 54	///
 55	/// Bounds apply before JSON allocation. Nested maps reject duplicate keys,
 56	/// including escaped aliases, even in unsupported variants. JSON's nesting limit
 57	/// remains enabled. Unknown variants are retained explicitly; recognized shapes
 58	/// are strict. Event coordinates are claims, not proof of coherent assembly.
 59	/// This type deliberately has no wire Serialize implementation: a later API must
 60	/// encode u64 coordinates without JavaScript rounding.
 61	pub fn decode(bytes: &[u8]) -> Result<Decoded<'_>, Error> {
 62	    if !bytes.starts_with(b"KANC") {
 63	        return Ok(Decoded::Opaque);
 64	    }
 65	    if bytes.len() > MAX_FRAME {
 66	        return Err(Error::Limit);
 67	    }
 68	    let Some(&version) = bytes.get(4) else {
 69	        return Err(Error::Envelope);
 70	    };
 71	    if version != b'2' {
 72	        return Ok(Decoded::Unsupported(Unsupported::Envelope));
 73	    }
 74	    let length: [u8; 4] = bytes.get(5..9).ok_or(Error::Envelope)?.try_into().unwrap();
 75	    let length = u32::from_be_bytes(length) as usize;
 76	    if length > MAX_HEADER {
 77	        return Err(Error::Limit);
 78	    }
 79	    let end = 9usize.checked_add(length).ok_or(Error::Envelope)?;
 80	    let json = bytes.get(9..end).ok_or(Error::Envelope)?;
 81	    let body = &bytes[end..];
 82	    if body.len() > CHUNK {
 83	        return Err(Error::Limit);
 84	    }
 85	    let Unique(value) = serde_json::from_slice(json).map_err(|_| Error::Header)?;
 86	    let object = value.as_object().ok_or(Error::Header)?;
 87	    let version = object
 88	        .get("version")
 89	        .and_then(Value::as_u64)
 90	        .ok_or(Error::Header)?;
 91	    if version != 2 {
 92	        return Ok(Decoded::Unsupported(Unsupported::Version));
 93	    }
 94	    let observer = object
 95	        .get("observer")
 96	        .and_then(Value::as_str)
 97	        .ok_or(Error::Header)?;
 98	    if !matches!(observer, "collector" | "gateway") {
 99	        return Ok(Decoded::Unsupported(Unsupported::Observer));
100	    }
101	    let event = object
102	        .get("event")
103	        .and_then(Value::as_object)
104	        .ok_or(Error::Header)?;
105	    let kind = event
106	        .get("type")
107	        .and_then(Value::as_str)
108	        .ok_or(Error::Header)?;
109	    if !matches!(
110	        kind,
111	        "started"
112	            | "request-chunk"
113	            | "request-end"
114	            | "forwarding-intent"
115	            | "transport-link"
116	            | "http-metadata-chunk"
117	            | "http-metadata"
118	            | "response-head"
119	            | "response-chunk"
120	            | "terminal"
121	    ) {
122	        return Ok(Decoded::Unsupported(Unsupported::Event));
123	    }
124	    if kind == "terminal" {
125	        let outcome = event
126	            .get("outcome")
127	            .and_then(Value::as_str)
128	            .ok_or(Error::Header)?;
129	        if !matches!(outcome, "completed" | "outcome-unknown") {
130	            return Ok(Decoded::Unsupported(Unsupported::Outcome));
131	        }
132	    }
133	    // An absent clock claim is not the explicit null emitted by the recorder.
134	    if !object.contains_key("observed_at_unix_micros") {
135	        return Err(Error::Header);
136	    }
137	    // Serde's internally tagged unit variant accepts extra map entries even
138	    // with deny_unknown_fields. Do not silently discard fields from a recognized
139	    // forwarding intent; the struct variants retain their derived strict checks.
140	    if kind == "forwarding-intent" && event.len() != 1 {
141	        return Err(Error::Header);
142	    }
143	    let header: Header = serde_json::from_value(value).map_err(|_| Error::Header)?;
144	    if !identifier(&header.attempt)
145	        || matches!(&header.event, Event::TransportLink { exchange } if !identifier(exchange))
146	        || matches!(&header.event, Event::Started { method, route } if method.len()>32 || route.len()>2048)
147	    {
148	        return Err(Error::Header);
149	    }
150	    if !body.is_empty()
151	        && !matches!(
152	            header.event,
153	            Event::RequestChunk { .. }
154	                | Event::ResponseChunk { .. }
155	                | Event::HttpMetadataChunk { .. }
156	        )
157	    {
158	        return Err(Error::Body);
159	    }
160	    Ok(Decoded::Capture(Frame {
161	        header,
162	        body,
163	        header_span: 9..end,
164	        body_span: end..bytes.len(),
165	    }))
166	}
167	
168	fn identifier(s: &str) -> bool {
169	    s.len() == 64
170	        && s.bytes()
171	            .all(|b| b.is_ascii_digit() || (b'a'..=b'f').contains(&b))
172	}
173	
174	// Deserialize without JSON map's last-write-wins semantics. Constructing Value
175	// only after rejecting each duplicate lets variant detection remain forward
176	// compatible without hiding ambiguous fields inside unknown events.
177	struct Unique(Value);
178	impl<'de> Deserialize<'de> for Unique {
179	    fn deserialize<D: Deserializer<'de>>(d: D) -> Result<Self, D::Error> {
180	        struct Strict;
181	        impl<'de> Visitor<'de> for Strict {
182	            type Value = Unique;
183	            fn expecting(&self, f: &mut fmt::Formatter) -> fmt::Result {
184	                f.write_str("unambiguous JSON")
185	            }
186	            fn visit_bool<E: de::Error>(self, v: bool) -> Result<Unique, E> {
187	                Ok(Unique(Value::Bool(v)))
188	            }
189	            fn visit_i64<E: de::Error>(self, v: i64) -> Result<Unique, E> {
190	                Ok(Unique(Value::Number(v.into())))
191	            }
192	            fn visit_u64<E: de::Error>(self, v: u64) -> Result<Unique, E> {
193	                Ok(Unique(Value::Number(v.into())))
194	            }
195	            fn visit_f64<E: de::Error>(self, v: f64) -> Result<Unique, E> {
196	                Number::from_f64(v)
197	                    .map(|n| Unique(Value::Number(n)))
198	                    .ok_or_else(|| E::custom("nonfinite JSON"))
199	            }
200	            fn visit_str<E: de::Error>(self, v: &str) -> Result<Unique, E> {
201	                Ok(Unique(Value::String(v.into())))
202	            }
203	            fn visit_unit<E: de::Error>(self) -> Result<Unique, E> {
204	                Ok(Unique(Value::Null))
205	            }
206	            fn visit_seq<A: SeqAccess<'de>>(self, mut seq: A) -> Result<Unique, A::Error> {
207	                let mut values = Vec::new();
208	                while let Some(Unique(v)) = seq.next_element()? {
209	                    values.push(v);
210	                }
211	                Ok(Unique(Value::Array(values)))
212	            }
213	            fn visit_map<A: MapAccess<'de>>(self, mut map: A) -> Result<Unique, A::Error> {
214	                let mut values = Map::new();
215	                while let Some(key) = map.next_key::<String>()? {
216	                    if values.contains_key(&key) {
217	                        return Err(de::Error::custom("duplicate JSON key"));
218	                    }
219	                    let Unique(value) = map.next_value()?;
220	                    values.insert(key, value);
221	                }
222	                Ok(Unique(Value::Object(values)))
223	            }
224	        }
225	        d.deserialize_any(Strict)
226	    }
227	}

