//! Experimental body capture. Queue admission is independent of provider success.
use crate::{evidence_delivery, evidence_service::hex, evidence_spool::Spool, sign::Identity};
use rand::RngCore;
use serde::{Deserialize, Serialize};
use sha2::{Digest, Sha256};
use std::time::{Duration, Instant, SystemTime, UNIX_EPOCH};
use tokio::io::{AsyncWrite, AsyncWriteExt};

pub const CHUNK: usize = 64 * 1024;
pub const MAX_REQUEST: usize = 16 * 1024 * 1024;
const MAGIC: &[u8; 5] = b"KANC2";

#[derive(Debug, Clone, Copy, Serialize, Deserialize, PartialEq, Eq)]
#[serde(rename_all = "kebab-case")]
pub enum Observer {
    Collector,
    Gateway,
}
#[derive(Debug, Clone, Copy, Serialize, Deserialize, PartialEq, Eq)]
#[serde(rename_all = "kebab-case")]
pub enum Outcome {
    Completed,
    OutcomeUnknown,
}
#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(tag = "type", rename_all = "kebab-case", deny_unknown_fields)]
pub enum Event {
    Started {
        method: String,
        route: String,
    },
    RequestChunk {
        offset: u64,
    },
    RequestEnd {
        bytes: u64,
    },
    ForwardingIntent,
    TransportLink {
        exchange: String,
    },
    HttpMetadataChunk {
        direction: String,
        offset: u64,
        total: u64,
    },
    HttpMetadata {
        direction: String,
        headers: Vec<(String, String)>,
        omitted: Vec<String>,
    },
    ResponseHead {
        status: u16,
    },
    ResponseChunk {
        offset: u64,
    },
    Terminal {
        outcome: Outcome,
    },
}
#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct Header {
    pub version: u8,
    pub attempt: String,
    pub observer: Observer,
    pub ordinal: u64,
    pub observed_at_unix_micros: Option<u64>,
    pub elapsed_micros: u64,
    pub unconfirmed_before: u64,
    pub event: Event,
}
/// Volatile observation, not a remotely acknowledged completeness certificate.
#[derive(Debug, Clone, Serialize, Deserialize)]

