  1	//! Canonical signed recovery observations. Authentication is not claim truth.
  2	//!
  3	//! This pure codec neither opens a bundle nor verifies member/output commitments,
  4	//! loss coverage, restoration membership, publication state or durable storage.
  5	//! Those checks belong to the complete bundle verifier before any mutation.
  6	use crate::{
  7	    evidence::{self, Error},
  8	    sign::Identity,
  9	};
 10	use atproto_dasl::{Cid, Ipld};
 11	use std::collections::BTreeMap;
 12	
 13	pub const MAX_ENVELOPE: usize = 16 * 1024;
 14	pub const DOMAIN: &str = "tools.kan.recovery.observation.v1";
 15	type Result<T> = std::result::Result<T, Error>;
 16	fn invalid(reason: &str) -> Error {
 17	    Error::Schema(reason.into())
 18	}
 19	fn require(ok: bool, reason: &str) -> Result<()> {
 20	    if ok {
 21	        Ok(())
 22	    } else {
 23	        Err(invalid(reason))
 24	    }
 25	}
 26	fn map<const N: usize>(fields: [(&str, Ipld); N]) -> Ipld {
 27	    Ipld::Map(fields.into_iter().map(|(k, v)| (k.into(), v)).collect())
