135	    let fields: &[&str] = match event {
136	        "created" => &["recipe", "member", "frontier"],
137	        "unavailable" => &["member", "entries"],
138	        "restored" => &["member", "cid", "length", "candidate"],
139	        "publication-intent" => &["attempt", "member", "restorations", "output", "frontier"],
140	        "publication-observed" => &["attempt", "intent", "output", "frontier"],
141	        "publication-failed" => &["attempt", "intent", "reason"],
142	        _ => return Err(invalid("event")),
143	    };
144	    let b = closed(v, fields, "body-fields")?;
145	    if let Some(v) = b.get("member") {
146	        blob(v, 32)?;
147	    }
148	    if let Some(v) = b.get("frontier") {
149	        frontier(v)?;
150	    }
151	    match event {
152	        "created" => require(b["recipe"] == Ipld::Integer(1), "recipe")?,
153	        "unavailable" => {
154	            let Ipld::List(entries) = &b["entries"] else {
155	                return Err(invalid("entries-bound"));
156	            };
157	            require((1..=32).contains(&entries.len()), "entries-bound")?;
158	            let mut previous = None;
159	            for entry in entries {
160	                let e = closed(
161	                    entry,
162	                    &["occurrence", "cid", "expectedLength", "state"],
163	                    "entry-fields",
164	                )?;
165	                let occurrence = if e["occurrence"] == Ipld::Null {
166	                    None
167	                } else {
168	                    Some(uint(
169	                        &e["occurrence"],
170	                        true,
171	                        evidence::MAX_SAFE_INTEGER as u64,
172	                    )?)
173	                };
174	                let cid = link(&e["cid"], 0x55)?;
175	                let length = if e["expectedLength"] == Ipld::Null {
176	                    None
177	                } else {
178	                    Some(uint(&e["expectedLength"], true, 4 * 1024 * 1024)?)
179	                };
180	                require(
181	                    occurrence.is_none() || length.is_some(),
182	                    "occurrence-length",
