189	                let coordinate = (
190	                    occurrence.is_none(),
191	                    occurrence.unwrap_or(0),
192	                    cid.to_string(),
193	                );
194	                require(
195	                    previous.as_ref().is_none_or(|p| p < &coordinate),
196	                    "entry-order-unique",
197	                )?;
198	                previous = Some(coordinate);
199	            }
200	        }
201	        "restored" => {
202	            link(&b["cid"], 0x55)?;
203	            link(&b["candidate"], 0x55)?;
204	            uint(&b["length"], true, 4 * 1024 * 1024)?;
205	            require(b["cid"] == b["candidate"], "candidate-cid")?;
206	        }
207	        "publication-intent" => {
208	            blob(&b["attempt"], 16)?;
209	            blob(&b["restorations"], 32)?;
210	            blob(&b["output"], 32)?;
211	        }
212	        "publication-observed" => {
213	            blob(&b["attempt"], 16)?;
214	            link(&b["intent"], 0x71)?;
215	            blob(&b["output"], 32)?;
216	        }
217	        "publication-failed" => {
218	            blob(&b["attempt"], 16)?;
219	            link(&b["intent"], 0x71)?;
220	            require(
221	                matches!(&b["reason"],Ipld::String(s) if matches!(s.as_str(),"source-changed"|"invalid-candidate"|"destination-conflict"|"budget"|"io"|"verification")),
