230	/// Authenticate one observation from genesis or an authenticated predecessor.
231	/// No claim about the member, loss vector, candidates or publication is accepted
232	/// merely because its observer signed it. Full state replay remains mandatory.
233	pub fn authenticate(
234	    bytes: &[u8],
235	    context: &Context,
236	    previous: Option<&Authenticated>,
237	) -> Result<Authenticated> {
238	    context.validate()?;
239	    require(bytes.len() <= MAX_ENVELOPE, "envelope-bound")?;
240	    let env = evidence::canonical_value(bytes, MAX_ENVELOPE)
241	        .map_err(|_| invalid("envelope-canonical"))?;
242	    let env = closed(&env, &["statement", "signature"], "envelope-fields")?;
243	    let Ipld::Bytes(statement) = &env["statement"] else {
244	        return Err(invalid("statement-bytes"));
245	    };
246	    let value = evidence::canonical_value(statement, MAX_ENVELOPE)
247	        .map_err(|_| invalid("statement-canonical"))?;
248	    let st = closed(
249	        &value,
250	        &[
251	            "version",
252	            "domain",
253	            "bundle",
254	            "profile",
255	            "archive",
256	            "scope",
257	            "issuer",
258	            "observer",
259	            "sequence",
260	            "previous",
261	            "sampledAt",
262	            "event",
263	            "body",
264	        ],
265	        "statement-fields",
266	    )?;
267	    require(
268	        st["version"] == Ipld::Integer(1) && st["domain"] == Ipld::String(DOMAIN.into()),
269	        "protocol",
270	    )?;
271	    for name in ["bundle", "archive", "scope"] {
272	        blob(&st[name], 32)?;
273	    }
274	    for name in ["issuer", "observer"] {
275	        let s = evidence::string(&st[name], 80).map_err(|_| invalid("did-key"))?;
276	        did(s)?;
277	    }
278	    require(matches!(st["profile"], Ipld::Integer(2 | 3)), "profile")?;
279	    require(
280	        st["bundle"] == Ipld::Bytes(context.bundle.to_vec())
281	            && st["archive"] == Ipld::Bytes(context.archive.to_vec())
282	            && st["scope"] == Ipld::Bytes(context.scope.to_vec())
283	            && st["profile"] == Ipld::Integer(context.profile.into())
284	            && st["issuer"] == Ipld::String(context.issuer.clone())
285	            && st["observer"] == Ipld::String(context.observer.clone()),
286	        "context-binding",
287	    )?;
288	    let sequence = uint(&st["sequence"], true, evidence::MAX_SAFE_INTEGER as u64)?;
289	    uint(&st["sampledAt"], false, evidence::MAX_SAFE_INTEGER as u64)?;
290	    if let Some(previous) = previous {
291	        require(&previous.context == context, "previous-context")?;
292	        require(sequence == previous.sequence + 1, "sequence")?;
293	        require(link(&st["previous"], 0x71)? == &previous.cid, "predecessor")?;
294	    } else {
295	        require(sequence == 1 && st["previous"] == Ipld::Null, "genesis")?;
296	    }
297	    let event = evidence::string(&st["event"], 32).map_err(|_| invalid("event"))?;
298	    // Validate the closed variant before its positional rule for useful errors.
299	    body(event, &st["body"])?;
300	    require((event == "created") == (sequence == 1), "created-position")?;
301	    let cid = crate::cid::content_cid(&value).map_err(|_| invalid("statement-cid"))?;
302	    let signature = blob(&env["signature"], 64)?;
303	    const ORDER: [u8; 32] = [
304	        0xff, 0xff, 0xff, 0xff, 0, 0, 0, 0, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xbc,
305	        0xe6, 0xfa, 0xad, 0xa7, 0x17, 0x9e, 0x84, 0xf3, 0xb9, 0xca, 0xc2, 0xfc, 0x63, 0x25, 0x51,
306	    ];
307	    const HALF: [u8; 32] = [
308	        0x7f, 0xff, 0xff, 0xff, 0x80, 0, 0, 0, 0x7f, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff,
309	        0xde, 0x73, 0x7d, 0x56, 0xd3, 0x8b, 0xcf, 0x42, 0x79, 0xdc, 0xe5, 0x61, 0x7e, 0x31, 0x92,
310	        0xa8,
311	    ];
312	    if signature[..32].iter().all(|b| *b == 0)
313	        || signature[..32] >= ORDER[..]
314	        || signature[32..].iter().all(|b| *b == 0)
315	        || signature[32..] > HALF[..]
316	    {
317	        return Err(invalid("signature-range"));
318	    }
319	    require(
320	        crate::sign::verify(&context.observer, &preimage(&cid)?, signature),
321	        "signature-invalid",
322	    )?;
323	    Ok(Authenticated {
324	        context: context.clone(),
325	        bytes: bytes.to_vec(),
326	        statement: statement.clone(),
327	        value,
328	        cid,
329	        sequence,
330	    })
331	}
332	
333	/// Pure signing for an already validated recovery operation. Callers must first
334	/// establish the semantic truth and allowed transition; this is not a writer API.
335	/// Encoded input is bounded and canonical before any signature is produced.
336	pub fn sign_claim(
337	    statement: &[u8],
338	    identity: &Identity,
339	    context: &Context,
340	    previous: Option<&Authenticated>,
341	) -> Result<Authenticated> {
342	    require(identity.did() == context.observer, "signer-context")?;
343	    let value = evidence::canonical_value(statement, MAX_ENVELOPE)
344	        .map_err(|_| invalid("statement-canonical"))?;
345	    let cid = crate::cid::content_cid(&value).map_err(|_| invalid("statement-cid"))?;
346	    let signature = identity
347	        .sign(&preimage(&cid)?)
348	        .map_err(|_| invalid("signing-failed"))?;
349	    let bytes = encode(&map([
350	        ("statement", Ipld::Bytes(statement.to_vec())),
351	        ("signature", Ipld::Bytes(signature)),
352	    ]))?;
353	    authenticate(&bytes, context, previous)
354	}

